CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, username text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', avatar text NOT NULL DEFAULT '🏇', referral_code text NOT NULL UNIQUE CHECK(referral_code ~ '^[A-Z0-9]{6}$'), referred_by uuid REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT UPDATE(username,phone,avatar) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.wallets (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, balance bigint NOT NULL DEFAULT 10000 CHECK(balance>=0));
GRANT SELECT ON public.wallets TO authenticated; GRANT ALL ON public.wallets TO service_role;
ALTER TABLE public.wallets ENABLE ROW LEVEL SECURITY;
CREATE POLICY wallet_read ON public.wallets FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.coin_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), amount bigint NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.coin_transactions TO authenticated; GRANT ALL ON public.coin_transactions TO service_role;
ALTER TABLE public.coin_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY transaction_read ON public.coin_transactions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.coin_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), kind text NOT NULL CHECK(kind IN ('recharge','withdrawal')), amount bigint NOT NULL CHECK(amount BETWEEN 1 AND 1000000), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now(), reviewed_by uuid, reviewed_at timestamptz);
GRANT SELECT ON public.coin_requests TO authenticated; GRANT ALL ON public.coin_requests TO service_role;
ALTER TABLE public.coin_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY request_read ON public.coin_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.game_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), win_rate integer NOT NULL DEFAULT 20 CHECK(win_rate BETWEEN 0 AND 100));
GRANT SELECT,INSERT,UPDATE ON public.game_settings TO authenticated; GRANT ALL ON public.game_settings TO service_role;
ALTER TABLE public.game_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_read ON public.game_settings FOR SELECT TO authenticated USING(true);
CREATE POLICY settings_admin ON public.game_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.player_races (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), stake bigint NOT NULL CHECK(stake>0), payout bigint NOT NULL, bet_type text NOT NULL, picks integer[] NOT NULL, finish_order integer[] NOT NULL, finish_times double precision[] NOT NULL, win_rate integer NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), settled_at timestamptz);
GRANT SELECT ON public.player_races TO authenticated; GRANT ALL ON public.player_races TO service_role;
ALTER TABLE public.player_races ENABLE ROW LEVEL SECURITY;
CREATE POLICY race_read ON public.player_races FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX one_active_race ON public.player_races(user_id) WHERE settled_at IS NULL;
CREATE FUNCTION public.create_player_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE code text; BEGIN LOOP code:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,6)); EXIT WHEN NOT EXISTS(SELECT 1 FROM public.profiles WHERE referral_code=code); END LOOP; INSERT INTO public.profiles(id,username,referral_code) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'username','Player'),30),code); INSERT INTO public.wallets(user_id) VALUES(NEW.id); INSERT INTO public.coin_transactions(user_id,amount,reason) VALUES(NEW.id,10000,'Welcome coins'); RETURN NEW; END $$;
CREATE TRIGGER create_player AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_player_profile();
CREATE FUNCTION public.claim_referral(code text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ref uuid; me uuid:=auth.uid(); BEGIN IF me IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; PERFORM 1 FROM public.profiles WHERE id=me FOR UPDATE; IF EXISTS(SELECT 1 FROM public.profiles WHERE id=me AND referred_by IS NOT NULL) THEN RAISE EXCEPTION 'Referral already claimed'; END IF; SELECT id INTO ref FROM public.profiles WHERE referral_code=upper(trim(code)); IF ref IS NULL OR ref=me THEN RAISE EXCEPTION 'Invalid referral code'; END IF; UPDATE public.profiles SET referred_by=ref WHERE id=me; PERFORM 1 FROM public.wallets WHERE user_id IN(me,ref) ORDER BY user_id FOR UPDATE; UPDATE public.wallets SET balance=balance+10 WHERE user_id IN(me,ref); INSERT INTO public.coin_transactions(user_id,amount,reason) VALUES(me,10,'Referral bonus'),(ref,10,'Referral bonus'); END $$;
REVOKE ALL ON FUNCTION public.claim_referral(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.claim_referral(text) TO authenticated;
CREATE FUNCTION public.request_coins(request_kind text,coins bigint) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; me uuid:=auth.uid(); bal bigint; BEGIN IF me IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF request_kind NOT IN('recharge','withdrawal') OR coins NOT BETWEEN 1 AND 1000000 THEN RAISE EXCEPTION 'Invalid amount'; END IF; SELECT balance INTO bal FROM public.wallets WHERE user_id=me FOR UPDATE; IF request_kind='withdrawal' THEN IF bal<coins THEN RAISE EXCEPTION 'Not enough coins'; END IF; UPDATE public.wallets SET balance=balance-coins WHERE user_id=me; INSERT INTO public.coin_transactions(user_id,amount,reason) VALUES(me,-coins,'Withdrawal reserved'); END IF; INSERT INTO public.coin_requests(user_id,kind,amount) VALUES(me,request_kind,coins) RETURNING id INTO rid; RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.request_coins(text,bigint) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.request_coins(text,bigint) TO authenticated;
CREATE FUNCTION public.review_coins(request_id uuid,approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.coin_requests; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; SELECT * INTO r FROM public.coin_requests WHERE id=request_id FOR UPDATE; IF r.id IS NULL OR r.status<>'pending' THEN RAISE EXCEPTION 'Request already reviewed'; END IF; IF (approve AND r.kind='recharge') OR (NOT approve AND r.kind='withdrawal') THEN UPDATE public.wallets SET balance=balance+r.amount WHERE user_id=r.user_id; INSERT INTO public.coin_transactions(user_id,amount,reason) VALUES(r.user_id,r.amount,CASE WHEN approve THEN 'Recharge approved' ELSE 'Withdrawal refunded' END); END IF; UPDATE public.coin_requests SET status=CASE WHEN approve THEN 'approved' ELSE 'rejected' END,reviewed_by=auth.uid(),reviewed_at=now() WHERE id=r.id; END $$;
REVOKE ALL ON FUNCTION public.review_coins(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_coins(uuid,boolean) TO authenticated;
CREATE FUNCTION public.open_player_race(player uuid,coins bigint,reward bigint,kind text,selection integer[],result_order integer[],times double precision[],rate integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; bal bigint; BEGIN SELECT balance INTO bal FROM public.wallets WHERE user_id=player FOR UPDATE; IF bal IS NULL OR coins<=0 OR bal<coins THEN RAISE EXCEPTION 'Not enough coins'; END IF; INSERT INTO public.player_races(user_id,stake,payout,bet_type,picks,finish_order,finish_times,win_rate) VALUES(player,coins,reward,kind,selection,result_order,times,rate) RETURNING id INTO rid; UPDATE public.wallets SET balance=balance-coins WHERE user_id=player; INSERT INTO public.coin_transactions(user_id,amount,reason) VALUES(player,-coins,'Race stake'); RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.open_player_race(uuid,bigint,bigint,text,integer[],integer[],double precision[],integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.open_player_race(uuid,bigint,bigint,text,integer[],integer[],double precision[],integer) TO service_role;
CREATE FUNCTION public.settle_player_race(race_id uuid) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.player_races; BEGIN SELECT * INTO r FROM public.player_races WHERE id=race_id AND user_id=auth.uid() FOR UPDATE; IF r.id IS NULL THEN RAISE EXCEPTION 'Race not found'; END IF; IF r.settled_at IS NULL THEN IF now()<r.started_at + make_interval(secs=65) THEN RAISE EXCEPTION 'Race still running'; END IF; UPDATE public.wallets SET balance=balance+r.payout WHERE user_id=r.user_id; INSERT INTO public.coin_transactions(user_id,amount,reason) VALUES(r.user_id,r.payout,'Race result'); UPDATE public.player_races SET settled_at=now() WHERE id=r.id; END IF; RETURN r.payout; END $$;
REVOKE ALL ON FUNCTION public.settle_player_race(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.settle_player_race(uuid) TO authenticated;